/**
 * Unit tests for XmlSerializerProvider constructor.
 * Since the constructor is protected, we use reflection or a subclass to access it.
 */
public class XmlSerializerProvider_XmlSerializerProvider_TriageGen2Test {

    /**
     * A subclass to expose the protected constructor for testing purposes.
     */
    private static class TestableXmlSerializerProvider extends XmlSerializerProvider {

        protected TestableXmlSerializerProvider(XmlSerializerProvider src) {
            super(src);
        }

        public XmlRootNameLookup getRootNameLookup() {
            try {
                Field field = XmlSerializerProvider.class.getDeclaredField("_rootNameLookup");
                field.setAccessible(true);
                return (XmlRootNameLookup) field.get(this);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    @Test
    public void testProtectedConstructorCopiesRootNameLookup() throws Exception {
        // Mock dependencies
        XmlRootNameLookup mockLookup = mock(XmlRootNameLookup.class);
        SerializationConfig mockConfig = mock(SerializationConfig.class);
        SerializerFactory mockFactory = mock(SerializerFactory.class);

        // We need an instance of XmlSerializerProvider to pass as 'src'
        // Using the public constructor: public XmlSerializerProvider(XmlRootNameLookup rootNames)
        // Note: In actual Jackson code, XmlSerializerProvider is often extended by DefaultSerializerProvider
        // We will use reflection to instantiate the source to ensure we have a real object if possible, 
        // or use the public constructor provided in the prompt.

        XmlSerializerProvider src = new XmlSerializerProvider(mockLookup);

        // Use reflection to invoke the protected constructor: protected XmlSerializerProvider(XmlSerializerProvider src)
        Constructor<XmlSerializerProvider> constructor = XmlSerializerProvider.class.getDeclaredConstructor(XmlSerializerProvider.class);
        constructor.setAccessible(true);

        XmlSerializerProvider result = constructor.newInstance(src);

        // Verify the internal _rootNameLookup was copied (shallow copy as per requirement)
        Field lookupField = XmlSerializerProvider.class.getDeclaredField("_rootNameLookup");
        lookupField.setAccessible(true);

        XmlRootNameLookup srcLookup = (XmlRootNameLookup) lookupField.get(src);
        XmlRootNameLookup resultLookup = (XmlRootNameLookup) lookupField.get(result);

        Assert.assertSame("The _rootNameLookup should be the same instance (shallow copy)", srcLookup, resultLookup);
        Assert.assertSame("The result should be the same instance as the lookup from src", srcLookup, resultLookup);
    }

    @Test
    public void testProtectedConstructorWithSubclass() {
        XmlRootNameLookup mockLookup = mock(XmlRootNameLookup.class);
        XmlSerializerProvider src = new XmlSerializerProvider(mockLookup);

        TestableXmlSerializerProvider result = new TestableXmlSerializerProvider(src);

        Assert.assertNotNull(result);
        Assert.assertSame(mockLookup, result.getRootNameLookup());
    }

